mapper.select:
SELECT CLCBA.CON_BANK_ACCOUNT_ID, CLCBA.BANK_ACCOUNT_ID, CLCBA.WITHDRAW_ID, CLCBA.CONTRACT_ID, CLCBA.BANK_ACCOUNT_TYPE, (select scvb.meaning from sys_code_value_b scvb, sys_code_b scb where scb.code = 'LON.ACCOUNT_TYPE' and scb.code_id = scvb.code_id and scvb.value = CLCBA.BANK_ACCOUNT_TYPE) as BANK_ACCOUNT_TYPE_N, CLCBA.DESCRIPTION, CLCBA.ENABLED_FLAG, CLCBA.LON_BANK_ACCOUNT_ID, CLCBA.ACCOUNT_SOURCE, (select scvb.meaning from sys_code_value_b scvb, sys_code_b scb where scb.code = 'LON_CON_ACCOUNT_SOURCE' and scb.code_id = scvb.code_id and scvb.value = CLCBA.ACCOUNT_SOURCE) as ACCOUNT_SOURCE_N, -- nvl( CB.BANK_NAME, CLBA.BANK_NAME ) AS BANK_NAME, CLCBA.BANK_ACCOUNT_NAME AS BANK_ACCOUNT_ID_N, CLCBA.BANK_BRANCH_NAME AS BANK_BRANCH_NAME, CLCBA.BANK_ACCOUNT_NAME AS BANK_ACCOUNT_NAME, CLCBA.BANK_ACCOUNT_NAME AS BANK_ACCOUNT_NAME_N, CLCBA.BANK_ACCOUNT_NUM AS BANK_ACCOUNT_NUM, CLCBA.OBJECT_VERSION_NUMBER FROM CT_LON_CONTRACT_BANK_ACCOUNT CLCBA LEFT JOIN CSH_BANK_ACCOUNT CBA ON CBA.BANK_ACCOUNT_ID=CLCBA.BANK_ACCOUNT_ID LEFT JOIN CSH_BANK CB ON CB.BANK_ID=CBA.BANK_ID
WHERE 1=1
AND CLCBA.CONTRACT_ID=#{contractId}
and CLCBA.BANK_ACCOUNT_TYPE = #{bankAccountType}
and CLCBA.withdraw_id = #{withdrawId}

select * from ( SELECT CLCBA.CON_BANK_ACCOUNT_ID, CLCBA.BANK_ACCOUNT_ID, CLCBA.WITHDRAW_ID old_Withdraw_Id, CLCBA.WITHDRAW_ID, CLCBA.CONTRACT_ID old_contract_Id, CLCBA.CONTRACT_ID, CLCBA.BANK_ACCOUNT_TYPE, (select scvb.meaning from sys_code_value_b scvb, sys_code_b scb where scb.code = 'LON.ACCOUNT_TYPE' and scb.code_id = scvb.code_id and scvb.value = CLCBA.BANK_ACCOUNT_TYPE) as BANK_ACCOUNT_TYPE_N, CLCBA.DESCRIPTION, CLCBA.ENABLED_FLAG, CLCBA.LON_BANK_ACCOUNT_ID, CLCBA.ACCOUNT_SOURCE, (select scvb.meaning from sys_code_value_b scvb, sys_code_b scb where scb.code = 'LON_CON_ACCOUNT_SOURCE' and scb.code_id = scvb.code_id and scvb.value = CLCBA.ACCOUNT_SOURCE) as ACCOUNT_SOURCE_N, -- nvl( CB.BANK_NAME, CLBA.BANK_NAME ) AS BANK_NAME, CLBA.BANK_ACCOUNT_NAME AS BANK_ACCOUNT_ID_N, CLBA.BANK_BRANCH_NAME AS BANK_BRANCH_NAME, CLBA.BANK_ACCOUNT_NAME AS BANK_ACCOUNT_NAME, CLBA.BANK_ACCOUNT_NAME AS BANK_ACCOUNT_NAME_N, CLBA.BANK_ACCOUNT_NUM AS BANK_ACCOUNT_NUM, CLCBA.OBJECT_VERSION_NUMBER FROM CT_LON_CONTRACT_BANK_ACCOUNT CLCBA LEFT JOIN CSH_BANK_ACCOUNT CBA ON CBA.BANK_ACCOUNT_ID=CLCBA.BANK_ACCOUNT_ID LEFT JOIN CSH_BANK CB ON CB.BANK_ID=CBA.BANK_ID LEFT JOIN CT_LON_BANK_ACCOUNT CLBA ON CLBA.BANK_ACCOUNT_ID=CLCBA.BANK_ACCOUNT_ID) ttt WHERE 1=1
AND ttt.CONTRACT_ID=#{oldcontractId}
and ttt.BANK_ACCOUNT_TYPE = #{bankAccountType}
and ttt.withdraw_id = #{oldWithdrawId}

SELECT
   COUNT(1)
FROM
    CT_LON_CONTRACT_BANK_ACCOUNT CLCBA
WHERE CLCBA.BANK_ACCOUNT_TYPE=#{bankAccountType}
AND   CLCBA.ENABLED_FLAG='Y'
AND   CLCBA.CONTRACT_ID=#{contractId}

   AND CLCBA.CON_BANK_ACCOUNT_ID !=#{conBankAccountId}

mapper.update:
   update CT_LON_CONTRACT_BANK_ACCOUNT set
BANK_ACCOUNT_ID=#{bankAccountId},
BANK_ACCOUNT_NUM=#{bankAccountNum},
BANK_ACCOUNT_NAME=#{bankAccountName},
BANK_BRANCH_NAME=#{bankBranchName}
 where CON_BANK_ACCOUNT_ID=#{conBankAccountId}
